import {
  createMatrxTransport,
  followServerJob,
  getRuntimeOperationsByLink
} from "@ai-matrx/agents/matrx";
function transportFor(backend) {
  return createMatrxTransport({
    resolveTarget: () => ({
      baseUrl: backend.baseUrl,
      policyHeaders: backend.headers,
      channel: backend.channel
    }),
    source: "runtime-reconnect"
  });
}
async function fetchOperationsByLink(backend, conversationId, signal) {
  return getRuntimeOperationsByLink(
    transportFor(backend),
    "conversation",
    conversationId,
    { limit: 5, ...signal ? { signal } : {} }
  );
}
function followConversationServerJob(backend, conversationId, options) {
  return followServerJob(transportFor(backend), {
    ...options,
    target: { linkKind: "conversation", linkId: conversationId }
  });
}
export {
  fetchOperationsByLink,
  followConversationServerJob
};
